<script setup lang="ts">
import { computed,ref } from 'vue'
import { useRouter } from 'vue-router'
import { usePlatform } from '../stores/platform'
import { useContinuity } from '../stores/continuity'
import type { PaperRule } from '../domain/continuity'
import PageHead from '../components/PageHead.vue'
const s=usePlatform(),c=useContinuity(),router=useRouter(),selected=ref(c.data.rules[0]!.id),form=ref<PaperRule>(JSON.parse(JSON.stringify(c.data.rules[0])))
const questions=computed(()=>s.data.questions.filter(q=>q.kind==='理论'&&q.status==='已入库'&&q.profession===form.value.profession&&q.level===form.value.level)),subjects=computed(()=>[...new Set(questions.value.map(q=>q.subject))]),knowledge=computed(()=>[...new Set(questions.value.filter(q=>form.value.subjects.includes(q.subject)).map(q=>q.knowledge))])
function load(){form.value=JSON.parse(JSON.stringify(c.data.rules.find(r=>r.id===selected.value)!))}
function generate(){s.run(()=>{c.generate(form.value);router.push('/papers')})}
</script>
<template><PageHead title="组卷标准比重" subtitle="设置题型题量、逐题分值、知识覆盖和题库来源，生成可校验的试卷。" eyebrow="题库应用 / 组卷规则"><RouterLink class="button" to="/papers">返回试卷</RouterLink><button class="button" @click="s.run(()=>c.saveRule(form))">校验并保存规则</button><button class="button primary" @click="generate">按当前规则生成</button></PageHead><section class="panel"><div class="filter-bar"><label class="inline-label">已存规则<select v-model="selected" @change="load"><option v-for="r in c.data.rules" :value="r.id">{{r.name}}</option></select></label><button class="button" @click="form.id='';form.name+='（副本）'">另存新规则</button></div><div class="form-grid" style="padding:24px"><label class="span-two">规则与试卷名称<input v-model="form.name"/></label><label>职业工种<select v-model="form.profession" @change="form.subjects=[];form.knowledge=[]"><option v-for="p in [...new Set(s.data.questions.map(q=>q.profession))]">{{p}}</option></select></label><label>技能等级<select v-model="form.level" @change="form.subjects=[];form.knowledge=[]"><option v-for="l in [...new Set(s.data.questions.filter(q=>q.profession===form.profession).map(q=>q.level))]">{{l}}</option></select></label><label>难度<select v-model="form.difficulty"><option>不限</option><option>容易</option><option>中等</option><option>较难</option></select></label><label>随机种子<input v-model.number="form.seed" type="number"/></label><div class="span-two"><h3>跨科目选题范围</h3><div class="filter-bar"><label v-for="subject in subjects" class="checkbox-label"><input type="checkbox" v-model="form.subjects" :value="subject" @change="form.knowledge=[]"/>{{subject}}</label></div><h3>知识点覆盖（未选择时使用全部知识点）</h3><div class="filter-bar"><label v-for="k in knowledge" class="checkbox-label"><input type="checkbox" v-model="form.knowledge" :value="k"/>{{k}}</label></div></div></div></section><section class="panel spaced"><div class="panel-head"><h3>题型与分值</h3><button class="button small" @click="form.rows.push({type:'简答题',count:1,score:10})">增加题型</button></div><table><thead><tr><th>题型</th><th>题量</th><th>每题分值</th><th>小计</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in form.rows"><td><select v-model="r.type"><option>单选题</option><option>多选题</option><option>判断题</option><option>简答题</option></select></td><td><input type="number" v-model.number="r.count" min="1" :aria-label="r.type+'题量'"/></td><td><input type="number" v-model.number="r.score" min="0.01" step="0.01" :aria-label="r.type+'每题分值'"/></td><td>{{r.count*r.score}}</td><td><button class="text-button" @click="form.rows.splice(i,1)">移除</button></td></tr></tbody></table><div class="panel-head"><strong>合计 {{form.rows.reduce((n,r)=>n+r.count,0)}} 道 / {{form.rows.reduce((n,r)=>n+r.count*r.score,0)}} 分</strong></div></section><section class="panel spaced"><div class="panel-head"><h3>1 + X + Y 来源比重</h3></div><div class="form-grid" style="padding:24px"><label v-for="(bank,i) in ['母题库','子题库','通用题库']">{{bank}}（%）<input v-model.number="form.banks[i]" type="number" min="0" max="100"/></label></div><p class="muted" style="padding:0 24px 24px">按总题量分配来源配额，余数依小数部分排序分配，再按题型分层抽取。库存不足或知识点覆盖不足会提示具体原因。</p></section></template>
